    let summary = validate_mac_receipt_value(path, &receipt)?;
    std::fs::write(path, serde_json::to_vec_pretty(&receipt)?).with_context(|| {
        format!("failed to update BitNet chat session receipt {}", path.display())
    })?;
    Ok(summary)
