    #[test]
    fn mac_serve_context_guardrail_error_maps_to_payload_too_large()
    -> Result<(), Box<dyn std::error::Error>> {
        let temp = tempfile::tempdir()?;
        let receipt_path = temp.path().join("m4srv-context-blocked.json");
        let context_envelope = mac_context_envelope_json(
            MacContextModelFamily::DenseSlm,
            MacContextRoute::Serve,
            "qwen2.5-0.5b-instruct-q8_0",
            M4_CONTEXT_4K_PROMPT_TOKENS + 1,
            true,
            8,
        );
        std::fs::write(
            &receipt_path,
            serde_json::to_vec_pretty(&serde_json::json!({
                "request_id": "m4srv-context-blocked",
                "context_envelope": context_envelope,
            }))?,
        )?;
        let error = anyhow!(
            "mac serve context guardrail blocked request: context_guardrail_blocked: prompt exceeds recorded envelope; receipt written to {}",
            receipt_path.display()
        );

        let reply = mac_serve_context_guardrail_error_reply(&error)?
            .ok_or_else(|| std::io::Error::other("expected guardrail reply"))?;
        let body: serde_json::Value = serde_json::from_slice(&reply.body)?;

        assert_eq!(reply.status, 413);
        assert_eq!(reply.reason, "Payload Too Large");
        assert_eq!(body["error"], "context_guardrail_blocked");
        assert_eq!(body["request_id"], "m4srv-context-blocked");
        assert_eq!(body["receipt_path"], receipt_path.display().to_string());
        assert_eq!(body["context_envelope"]["allowed"], false);
        assert_eq!(body["claim_boundary"]["unsupported_context_supported"], false);
        Ok(())
    }

    #[test]
    fn mac_serve_completion_request_accepts_prompt_or_chat_messages() {
        let prompt_request: MacServeCompletionRequest =
            serde_json::from_str(r#"{"prompt":"What is 2+2?"}"#).expect("prompt request");
        assert_eq!(prompt_request.prompt_text().expect("prompt"), "What is 2+2?");

        let chat_request: MacServeCompletionRequest = serde_json::from_str(
            r#"{"messages":[{"role":"system","content":"Be brief."},{"role":"user","content":"Name the capital of France."}]}"#,
        )
        .expect("chat request");
        assert_eq!(chat_request.prompt_text().expect("chat prompt"), "Name the capital of France.");
        assert_eq!(chat_request.system_prompt().as_deref(), Some("Be brief."));
    }

    #[test]
    fn mac_serve_host_loopback_detection_warns_only_for_non_loopback() {
        assert!(mac_serve_host_is_loopback("127.0.0.1"));
        assert!(mac_serve_host_is_loopback("localhost"));
        assert!(mac_serve_host_is_loopback("::1"));
        assert!(mac_serve_host_is_loopback("[::1]"));
        assert!(!mac_serve_host_is_loopback("0.0.0.0"));
        assert!(!mac_serve_host_is_loopback("192.168.1.5"));
    }

    #[test]
    fn mac_serve_check_url_parser_requires_http_host_port() {
        assert_eq!(
            MacServeCheckEndpoint::parse("http://127.0.0.1:8080").expect("url"),
            MacServeCheckEndpoint { host: "127.0.0.1".to_string(), port: 8080 }
        );
        assert_eq!(
            MacServeCheckEndpoint::parse("http://[::1]:8080").expect("ipv6 url"),
            MacServeCheckEndpoint { host: "::1".to_string(), port: 8080 }
        );
        assert!(MacServeCheckEndpoint::parse("https://127.0.0.1:8080").is_err());
        assert!(MacServeCheckEndpoint::parse("http://127.0.0.1").is_err());
        assert!(MacServeCheckEndpoint::parse("http://127.0.0.1:8080/path").is_err());
    }

    #[test]
    fn dense_local_server_smoke_receipt_validates_claim_boundaries()
    -> Result<(), Box<dyn std::error::Error>> {
        let temp = tempfile::tempdir()?;
        let receipt_path = temp.path().join("serve-smoke.json");
        let mut receipt = serde_json::json!({
            "schema_version": "1.0.0",
            "artifact_kind": "bitnet_apple_m4_dense_local_server_smoke",
            "operator_command": "mac serve-smoke",
            "result": "pass",
            "model_family": "dense-slm",
            "model_id": "qwen2.5-0.5b-instruct-q8_0",
            "requested_backend": APPLE_M4_CPU_NEON,
            "selected_backend": APPLE_M4_CPU_NEON,
            "runtime_api": "cpu",
            "fallback_used": false,
            "timeout_boundary": {
                "configured_seconds": 300,
                "enforced": false,
                "reached": false,
            },
            "checks": {
                "health": {"executed": true, "passed": true},
                "ready": {"executed": true, "passed": true},
                "models": {"executed": true, "passed": true},
                "one_shot_completion": {
                    "executed": true,
                    "passed": true,
                    "generated_tokens": 1,
                    "receipt_export": {"executed": true, "passed": true}
                },
                "streaming_completion": {
                    "executed": true,
                    "passed": true,
                    "generated_tokens": 1,
                    "receipt_export": {"executed": true, "passed": true}
                }
            },
            "claim_boundary": {
                "server_health_checked": true,
                "server_readiness_checked": true,
                "model_catalog_checked": true,
                "one_shot_completion_checked": true,
                "streaming_completion_checked": true,
                "receipt_export_checked": true,
                "dense_slm_only": true,
                "bitnet_serve_claimed": false,
                "production_readiness_claimed": false,
                "openai_compatibility_claimed": false,
                "bitnet_quality_claimed": false,
                "full_metal_inference_claimed": false,
                "mpsgraph_inference_claimed": false,
                "neural_engine_execution_claimed": false,
                "qk256_apple_claimed": false,
                "broad_performance_claim": false,
                "speedup_claim": false,
            },
        });

        let summary = validate_mac_receipt_value(&receipt_path, &receipt)?;
        assert_eq!(summary.artifact_kind, "bitnet_apple_m4_dense_local_server_smoke");
        assert_eq!(summary.generated_tokens, Some(2));

        receipt["claim_boundary"]["bitnet_serve_claimed"] = serde_json::json!(true);
        let err = validate_mac_receipt_value(&receipt_path, &receipt)
            .expect_err("BitNet serve claim must be rejected")
            .to_string();
        assert!(err.contains("bitnet_serve_claimed"));
        Ok(())
    }

